 for(let y=y0;y<=y1;y++)for(let x=0;x<W;x++){const i=y*W+x,o=own[i];if(o>1&&o!==WATER){if(blk[o]){hit.add(o);continue}own[i]=0;terr[o]--;n++}}
 ships=ships.filter(s=>s.a===1||blk[s.a]||Math.abs(s.y-p.y)>p.bh);
