 for(let q=0;q<22;q++){const an=BFR(0,6.283),v=BFR(40,150);b2Push({k:'d',x,y,vx:Math.cos(an)*v,vy:Math.sin(an)*v-BFR(60,140),c:q%2?[200,240,255]:[255,255,255],t0:now,life:BFR(500,950),sz:BFR(1.3,2.6),g:300})}
