 const visit=j=>{const o=own[j];if(o<2||o===WATER||binf[o]>0)return;if(blk[o]){hit.add(o);return}if(opt.take){own[j]=1;terr[1]++;bb(1,j)}else own[j]=0;terr[o]--;rem[o]++;n++};
