   if(xx<1||yy<1||xx>=W-1||yy>=H-1||(xx-px)**2+(yy-py)**2>h.r*h.r)continue;
   const j=yy*W+xx,o=own[j];if(o<2||o===WATER||blk[o]||binf[o]>0)continue;
