function end(win){
 clearInterval(timer);phase='over';
 if(LV.net){netEndScreen(win);return}
 if(LV.ord){ordMapEnd(win);return}
 if(LV.free){scr(`<h1>${win?'🏆 Победа!':'💀 Поражение'}</h1><p>Свободная игра · монеты не начисляются</p><button data-a="fpplay">Играть снова</button><button class="s" data-a="fp">⚙️ Настройки партии</button><button class="s" data-a="home">Главное меню</button>`);hap(win?'heavy':'rigid');return}
 if(win){sv.coins+=Math.round(200*(LV.cm||1));sv.done=Math.max(sv.done,cur+1)}persist();
 if(win&&cur===4&&!sv.portal){sv.portal=1;persist();hap('heavy');portal();return}
 shop(win?`🏆 Уровень ${cur+1} пройден!`:'💀 Поражение',`За выживание: +${earned} 💰${win?' · бонус за победу +'+Math.round(200*(LV.cm||1))+' 💰':''}`,{win});hap(win?'heavy':'rigid');
}
let tt;function toast(m){const t=$('toast');t.textContent=m;t.style.opacity=1;clearTimeout(tt);tt=setTimeout(()=>t.style.opacity=0,1800)}
function tap(sx,sy){
 if(expand&&expand.duel)return;
 const x=Math.floor((sx-cam.ox)/cam.s),y=Math.floor((sy-cam.oy)/cam.s);
 if(x<0||y<0||x>=W||y>=H)return;
 if(LV.net&&netRole==='guest'){if(phase!=='play')return toast('Хозяин выбирает старт…');if(aim>=0){const i=aim;aim=-1;cds[i]=5;netSend({t:'ab',i,x,y});hap('light');abUI();return}netSend({t:'tap',x,y,p:+$('pct').value});hap('light');return}
 if(aim>=0&&phase==='play'){fireAim(x,y);return}
 const t=own[y*W+x];
 if(phase==='pick'){
  if(t!==0)return toast('Выбери свободную сушу');
  spawn(1,x,y);troops[1]+=40*UPX.s;if(LV.hell)startIsle=isle[y*W+x];startBots(x,y);if(LV.net)netPick();calcAdj();if(hasSpell('timeback'))startSnap=mkSnap();phase='play';draw();hud();timer=setInterval(step,100);hap('medium');return;
 }
 if(phase!=='play'||t===1||t===WATER)return;
 if(LV.ord&&t>1&&ordAl[t])return toast(`🤝 ${NAMES[t-1]} — твой союзник. Чтобы напасть, разорви союз в 🤝 Дипломатии`);
 const ex=attacks.findIndex(k=>k.a===1&&k.t===t);
 if(ex>=0){const k=attacks.splice(ex,1)[0];troops[1]+=k.tr;hap('rigid');return toast(`Атака отменена · вернулось ${k.tr|0}`)}
 const amt=troops[1]*($('pct').value/100);
 if(amt<5)return toast('Мало войск');
 if(!(adj[P+t]&&(!LV.isl||onMass(comp[y*W+x])))){
  if(!LV.isl)return toast('Нет общей границы');
  if(LV.hell&&!unlocked)return toast('🔒 Другие острова недоступны, пока не захвачен твой');
  if(launchShip(1,x,y,amt)){hap('medium');return toast(`⛵ Корабль отправлен · ${amt|0} войск`)}
  return toast('Корабль не доплывёт');
 }
 lastT=t;if(LV.ord&&t>1)ordTrust[t]=0;launch(1,t,amt);hap('light');toast(`Атака · ${amt|0} войск (тап ещё раз — отмена)`);
}
function zoomAt(x,y,f){
 const ns=Math.max(cam.fit*.9,Math.min(30,cam.s*f)),k=ns/cam.s;
 cam.ox=x-(x-cam.ox)*k;cam.oy=y-(y-cam.oy)*k;cam.s=ns;
}
const ptr=new Map();let multi=false,prev=null;
const rel=e=>{const r=view.getBoundingClientRect();return{x:e.clientX-r.left,y:e.clientY-r.top}};
view.addEventListener('pointerdown',e=>{
 view.setPointerCapture(e.pointerId);const p=rel(e);ptr.set(e.pointerId,{...p,x0:p.x,y0:p.y});
 if(ptr.size>1){multi=true;prev=pinchInfo()}
});
function pinchInfo(){const a=[...ptr.values()];return{d:Math.hypot(a[0].x-a[1].x,a[0].y-a[1].y)||1,mx:(a[0].x+a[1].x)/2,my:(a[0].y+a[1].y)/2}}
view.addEventListener('pointermove',e=>{
 const q=ptr.get(e.pointerId);if(!q)return;const p=rel(e);
 if(ptr.size===1){cam.ox+=p.x-q.x;cam.oy+=p.y-q.y;q.x=p.x;q.y=p.y}
 else{q.x=p.x;q.y=p.y;const c=pinchInfo();zoomAt(c.mx,c.my,c.d/prev.d);cam.ox+=c.mx-prev.mx;cam.oy+=c.my-prev.my;prev=c}
});
const up=e=>{
 const q=ptr.get(e.pointerId);if(!q)return;ptr.delete(e.pointerId);
 if(!multi&&e.type==='pointerup'&&Math.hypot(q.x-q.x0,q.y-q.y0)<8)tap(q.x,q.y);
 if(ptr.size===0)multi=false;
};
view.addEventListener('pointerup',up);view.addEventListener('pointercancel',up);
view.addEventListener('wheel',e=>{e.preventDefault();const p=rel(e);zoomAt(p.x,p.y,e.deltaY<0?1.15:1/1.15)},{passive:false});
document.addEventListener('visibilitychange',()=>{persist();if(document.hidden&&phase==='play')pause()});$('pct').oninput=pv;pv();
/* ===== Сетевая игра (WebRTC без сервера) =====
   Хозяин (игрок 1) считает всю игру, гость (игрок 2) шлёт тапы и получает состояние карты.
   У гостя индексы игроков 1<->2 поменяны местами, чтобы он видел себя как «игрока 1». */
let netUp=0,netPC=null,netDC=null,netRole=null,netG=0,netSeed=0,netPeerName='',netInit=null,netLast=null,netIdx=null,netDirty=0;
const NET16=['blitz','breakthrough','mobil','reinforce','sabotage','blessing','frost','meteor','whirl','wedge','bombard','regen','eruption','steal','golden','infinity'].filter(id=>ABS[id]);
const NET_ALL=Object.keys(ABS).filter(id=>!ABS[id].ps&&!DOM[id]);
const NET_M=NET_ALL.filter(id=>ABS[id].m),NET_A=NET_ALL.filter(id=>!ABS[id].m&&!ABS[id].sh),NET_SH=NET_ALL.filter(id=>ABS[id].sh);
const NET_DEF=['blitz','breakthrough','mobil',null,null];
const netOk=(x,i)=>x&&NET_ALL.includes(x)&&(!!ABS[x].m)===(i>2)?x:null;
let netCfg=Object.assign({map:'cont',theme:0,size:'M',bots:2,goal:60,pre:1,sl:NET_DEF.slice(),rar:3,th:128,inv:0},sv.netcfg);
if(!Array.isArray(netCfg.sl))netCfg.sl=NET_DEF.slice();
netCfg.sl=[0,1,2,3,4].map(i=>netOk(netCfg.sl[i],i));
let netGS=[0,1,2,3,4].map(i=>netOk(Array.isArray(sv.netgs)?sv.netgs[i]:NET_DEF[i],i)),netGSh=NET_DEF.slice(),netGSact=NET_DEF.slice(),ncd=[0,0,0,0,0],grefl=0,ghounds=[],gdsA=null,gdsB=null;
const netSlots=()=>{const a=(netRole==='host'?netCfg.sl:(netInit&&netInit.gs)||NET_DEF).slice(0,5).map((x,i)=>netOk(x,i));while(a.length<5)a.push(null);return a};
const netRle=m=>{const r=[];let v=0,n=0;for(let i=0;i<m.length;i++){if(m[i]===v)n++;else{r.push(n);v=m[i];n=1}}r.push(n);return r};
const netUnrle=(r,len)=>{const m=new Uint8Array(len);let i=0,v=0;for(const n of r){if(v)m.fill(1,i,i+n);i+=n;v^=1}return m};
const netAbOpts=(cur,none,m)=>`<option value="">${none}</option>`+(m?[['Магия (тап по карте)',NET_M]]:[['Способности',NET_A],['Тени',NET_SH]]).map(([g,l])=>`<optgroup label="${g}">${l.map(id=>`<option value="${id}" ${id===cur?'selected':''}>${ABS[id].ic} ${ABS[id].n}</option>`).join('')}</optgroup>`).join('');
const netSelects=(pre,arr)=>[0,1,2,3,4].map(k=>`<select class="ti" data-nf="${pre}${k}">${netAbOpts(arr[k],(k>2?'— магия ':'— способность ')+(k>2?k-2:k+1)+' —',k>2)}</select>`).join('');
const NET_ICE={iceServers:[{urls:'stun:stun.l.google.com:19302'}]};
const NET_SW=new Uint8Array(256).map((_,i)=>i);NET_SW[1]=2;NET_SW[2]=1;
const netSt=m=>{const e=$('nst');if(e)e.textContent=m};

// ---------- коды подключения ----------
const b64=u=>{let s='';for(let i=0;i<u.length;i+=8192)s+=String.fromCharCode.apply(null,u.subarray(i,i+8192));return btoa(s)};
const unb64=t=>Uint8Array.from(atob(t),c=>c.charCodeAt(0));
async function pack(s){
 const b=new TextEncoder().encode(s);
 if(window.CompressionStream){try{const cs=new CompressionStream('deflate-raw'),w=cs.writable.getWriter();w.write(b);w.close();return 'Z'+b64(new Uint8Array(await new Response(cs.readable).arrayBuffer()))}catch(e){}}
 return 'R'+b64(b);
}
async function unpack(c){
 c=c.replace(/\s+/g,'');const k=c[0],b=unb64(c.slice(1));
 if(k==='Z'){const ds=new DecompressionStream('deflate-raw'),w=ds.writable.getWriter();w.write(b);w.close();return new TextDecoder().decode(await new Response(ds.readable).arrayBuffer())}
 return new TextDecoder().decode(b);
}
async function netCopy(id){
 const ta=$(id);if(!ta)return;
 try{await navigator.clipboard.writeText(ta.value);toast('Скопировано')}
 catch(e){ta.focus();ta.select();try{document.execCommand('copy');toast('Скопировано')}catch(e2){toast('Выдели текст и скопируй вручную')}}
}
async function netPaste(id){
 try{const t=await navigator.clipboard.readText();$(id).value=t;toast('Вставлено')}catch(e){toast('Вставь вручную: долгое нажатие на поле')}
}

// ---------- соединение ----------
function netClose(){netUp=0;const pc=netPC,dc=netDC;netPC=null;netDC=null;try{dc&&dc.close()}catch(e){}try{pc&&pc.close()}catch(e){}}
function netMk(){
 netClose();
 const pc=new RTCPeerConnection(NET_ICE);netPC=pc;
 pc.onconnectionstatechange=()=>{if(pc===netPC&&(pc.connectionState==='failed'||pc.connectionState==='closed'))netLost()};
 setTimeout(()=>{if(pc===netPC&&!netUp&&pc.remoteDescription&&pc.connectionState!=='connected')netSt('⏳ Долго соединяюсь… если не выйдет — попробуйте «Через интернет»')},12000);
 return pc;
}
function netGather(pc){
 return new Promise(res=>{
  if(pc.iceGatheringState==='complete')return res();
  const t=setTimeout(done,3500);
  function done(){clearTimeout(t);pc.removeEventListener('icegatheringstatechange',ch);res()}
  function ch(){if(pc.iceGatheringState==='complete')done()}
  pc.addEventListener('icegatheringstatechange',ch);
 });
}
function netBind(dc){
 netDC=dc;dc.binaryType='arraybuffer';
 dc.onopen=()=>{netUp=1;if(netRole==='guest'){netSend({t:'hello',name:sv.set.name||myName});netSt('Соединено, жду хозяина…')}else netSt('Друг подключается…')};
 dc.onmessage=e=>netMsg(e.data);
 dc.onclose=()=>{if(dc===netDC)netLost()};
}
const netSend=o=>{if(netDC&&netDC.readyState==='open')netDC.send(typeof o==='string'||o instanceof ArrayBuffer?o:JSON.stringify(o))};
function netLost(){
 if(!netRole)return;
 const was=netUp;clearInterval(timer);netClose();phase='over';
 if(!was)scr(`<h1>😕 Не удалось соединиться</h1><p>Телефоны не смогли связаться напрямую. Так бывает, если Wi‑Fi изолирует устройства друг от друга, включён VPN или у кого-то мобильный интернет.</p><p>Попробуйте режим «Через интернет» — он работает с любой сетью (нужен только интернет у обоих).</p><button data-a="netroom">🌍 Создать комнату</button><button data-a="netroomjoin">🌍 Войти в комнату</button><button class="s" data-a="netmenu">← Назад</button>`);
 else scr(`<h1>🔌 Связь потеряна</h1><p>Соединение с другим игроком прервалось.</p><button data-a="netquit">В меню</button>`);
}
function netQuit(silent){
 netClose();netRole=null;netG=0;netPeerName='';netInit=null;netLast=null;clearInterval(timer);
 if(LV&&LV.net)LV=LEVELS[0];
 phase='menu';
 if(!silent)home();
}

// ---------- экраны ----------
function netMenu(){
 netQuit(true);
 scr(`<h1>🌐 Сетевая игра</h1><p>Два игрока по одному Wi‑Fi (или через раздачу с телефона). Сервер не нужен: телефоны соединяются напрямую, коды передаются через мессенджер.</p><button data-a="nethost">🎮 Создать игру</button><button data-a="netjoin">🔗 Присоединиться</button><div class="sec">Через интернет (если напрямую не выходит)</div><button data-a="netroom">🌍 Создать комнату</button><button data-a="netroomjoin">🌍 Войти по коду комнаты</button><div class="sh"><div>Как играть</div><div class="row"><div class="tx"><small>Хозяин создаёт игру и отправляет код другу, друг вставляет его и присылает код ответа. После подключения хозяин настраивает карту и ботов. Побеждает тот, кто первым захватит нужную долю суши или уничтожит соперника. Способности в сетевой игре отключены.</small></div></div></div><button class="s" data-a="home">← Назад</button>`);
}
function netCodeBlock(id,code){
 const share=tg&&tg.openTelegramLink?`<button class="s" data-a="netshare" data-id="${id}">✈️ Отправить в Telegram</button>`:'';
 return `<textarea id="${id}" class="ti" rows="3" readonly></textarea><button data-a="netcopy" data-id="${id}">📋 Копировать</button>${share}`;
}
// ---------- запасной канал: комната через публичный MQTT-брокер (работает в любой сети) ----------
const NET_BROKERS=['wss://broker.hivemq.com:8884/mqtt','wss://broker.emqx.io:8084/mqtt','wss://mqtt.eclipseprojects.io:443/mqtt','wss://test.mosquitto.org:8081/mqtt','wss://broker-cn.emqx.io:8084/mqtt'];
const NET_AL='ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
const mqStr=t=>{const b=new TextEncoder().encode(t);const o=new Uint8Array(2+b.length);o[0]=b.length>>8;o[1]=b.length&255;o.set(b,2);return o};
const mqCat=(...a)=>{let n=0;for(const x of a)n+=x.length;const o=new Uint8Array(n);let i=0;for(const x of a){o.set(x,i);i+=x.length}return o};
const mqPkt=(h,body)=>{const l=[];let n=body.length;do{let d=n%128;n=Math.floor(n/128);if(n)d|=128;l.push(d)}while(n);return mqCat(Uint8Array.of(h,...l),body)};
function netMqtt(room,role,idx){
 const all=window.NET_BROKERS||NET_BROKERS,urls=idx==null?all:[all[idx]],rt=room.slice(0,5),tin='tv1/'+rt+'/'+(role==='host'?'g':'h'),tout='tv1/'+rt+'/'+(role==='host'?'h':'g');
 const dc={readyState:'connecting',binaryType:'arraybuffer',onopen:null,onmessage:null,onclose:null,ws:null,get bufferedAmount(){return dc.ws?dc.ws.bufferedAmount:0},
  send(d){if(dc.readyState!=='open')return;const pl=typeof d==='string'?mqCat(Uint8Array.of(83),new TextEncoder().encode(d)):mqCat(Uint8Array.of(66),new Uint8Array(d.buffer?d.buffer.slice(d.byteOffset,d.byteOffset+d.byteLength):d));dc.ws.send(mqPkt(0x30,mqCat(mqStr(tout),pl)))},
  close(){dc.readyState='closed';clearInterval(dc.pt);try{dc.ws&&dc.ws.close()}catch(e){}}};
 return new Promise((res,rej)=>{
  let k=0;
  const next=()=>{
   if(k>=urls.length)return rej(new Error('Не удалось подключиться к серверу комнат'));
   const url=urls[k++];let ws,done=0,buf=new Uint8Array(0);
   const fail=()=>{if(done)return;done=1;try{ws.close()}catch(e){}next()};
   try{ws=new WebSocket(url,'mqtt')}catch(e){return next()}
   ws.binaryType='arraybuffer';const to=setTimeout(fail,7000);
   ws.onerror=()=>{if(!done)fail()};
   ws.onopen=()=>ws.send(mqPkt(0x10,mqCat(mqStr('MQTT'),Uint8Array.of(4,2,0,30),mqStr('tv'+Math.random().toString(36).slice(2,10)))));
   ws.onclose=()=>{if(!done){fail();return}if(dc.readyState==='open'){dc.readyState='closed';clearInterval(dc.pt);dc.onclose&&dc.onclose()}};
   ws.onmessage=e=>{
    buf=mqCat(buf,new Uint8Array(e.data));
    for(;;){
     if(buf.length<2)return;
     let n=0,m=1,i=1,b;do{if(i>=buf.length)return;b=buf[i++];n+=(b&127)*m;m*=128}while(b&128);
     if(buf.length<i+n)return;
     const h=buf[0],body=buf.subarray(i,i+n);buf=buf.subarray(i+n);const ty=h>>4;
     if(ty===2){if(body[1]!==0)return fail();ws.send(mqPkt(0x82,mqCat(Uint8Array.of(0,1),mqStr(tin),Uint8Array.of(0))))}
     else if(ty===9){if(done)continue;done=1;clearTimeout(to);dc.ws=ws;dc.readyState='open';dc.pt=setInterval(()=>{try{ws.send(Uint8Array.of(0xC0,0))}catch(e){}},20000);res(dc);dc.onopen&&dc.onopen()}
     else if(ty===3){
      const tl=(body[0]<<8)|body[1];let o=2+tl;if((h>>1)&3)o+=2;
      const kind=body[o],pl=body.subarray(o+1);
      if(dc.onmessage)dc.onmessage({data:kind===83?new TextDecoder().decode(pl):pl.slice().buffer});
     }
    }
   };
  };
  next();
 });
}
// хозяин пробует все серверы одновременно и берёт самый быстрый; номер сервера зашит в 6-м символе кода
function netMqttRace(room,role){
 const n=(window.NET_BROKERS||NET_BROKERS).length;
 return new Promise((res,rej)=>{
  let won=0,fails=0;
  for(let i=0;i<n;i++)netMqtt(room,role,i).then(dc=>{if(won){dc.close();return}won=1;res({dc,i})},()=>{if(++fails>=n&&!won)rej(new Error('Ни один сервер комнат не отвечает'))});
 });
}
async function netRoomOpen(role,room){
 let dc,code=room;
 if(role==='host'){const r=await netMqttRace(room,role);dc=r.dc;code=room+NET_AL[r.i]}
 else{const i=room.length>5?NET_AL.indexOf(room[5]):-1,n=(window.NET_BROKERS||NET_BROKERS).length;dc=await netMqtt(room,role,i>=0&&i<n?i:null)}
 netBind(dc);netUp=1;
 if(role==='guest'){dc.onopen&&dc.onopen();setTimeout(()=>{if(netDC===dc&&!netPeerName)netSt('❌ Комната не найдена или хозяин не в сети')},9000)}
 return code;
}
async function netRoomHost(){
 netQuit(true);netRole='host';
 const al='ABCDEFGHJKLMNPQRSTUVWXYZ23456789';let room='';for(let i=0;i<5;i++)room+=al[Math.random()*al.length|0];
 scr(`<h1>🌍 Создаю комнату…</h1><p>Подключаюсь к серверу комнат</p>`);
 try{room=await netRoomOpen('host',room)}catch(e){netRole=null;return scr(`<h1>Ошибка</h1><p>${esc(e.message||e)}. Проверьте интернет.</p><button class="s" data-a="netmenu">← Назад</button>`)}
 if(netRole!=='host')return;
 scr(`<h1>🌍 Комната готова</h1><p>Скажи другу этот код: он нажимает «Войти по коду комнаты».</p><input id="nco" class="ti" readonly style="text-align:center;font-size:40px;font-weight:800;letter-spacing:8px;padding:14px 0"><button data-a="netcopy" data-id="nco">📋 Копировать код</button>${tg&&tg.openTelegramLink?'<button class="s" data-a="netshare" data-id="nco">✈️ Отправить в Telegram</button>':''}<p id="nst" style="min-height:18px;font-size:12px">Жду друга…</p><button class="s" data-a="netmenu">← Назад</button>`);
 $('nco').value=room;
}
function netRoomJoin(){
 netQuit(true);netRole='guest';
 scr(`<h1>🌍 Войти в комнату</h1><p>Введи код комнаты от друга:</p><input id="nrc" class="ti" maxlength="6" placeholder="КОД" style="text-transform:uppercase;letter-spacing:4px;text-align:center;font-size:22px"><button data-a="netroomgo">Войти</button><p id="nst" style="min-height:18px;font-size:12px"></p><button class="s" data-a="netmenu">← Назад</button>`);
}
async function netRoomGo(){
 const room=($('nrc').value||'').trim().toUpperCase().replace(/[^A-Z0-9]/g,'');
 if(room.length<4)return netSt('Введи код комнаты');
 netSt('Подключаюсь…');netRole='guest';
 try{await netRoomOpen('guest',room)}catch(e){netSt('❌ '+(e.message||e))}
}
async function netHostStart(){
 if(!window.RTCPeerConnection)return toast('Этот браузер не поддерживает WebRTC');
 netRole='host';scr(`<h1>🎮 Создаю игру…</h1><p>Готовлю код (до нескольких секунд)</p>`);
 try{
  const pc=netMk(),dc=pc.createDataChannel('g');netBind(dc);
  await pc.setLocalDescription(await pc.createOffer());await netGather(pc);
  const code=await pack(JSON.stringify(pc.localDescription));
  if(pc!==netPC)return;
  scr(`<h1>🎮 Создать игру</h1><p>1. Отправь код другу и попроси нажать «Присоединиться».</p>${netCodeBlock('nco')}<p>2. Когда друг пришлёт код ответа, вставь его:</p><textarea id="nci" class="ti" rows="3" placeholder="Код ответа"></textarea><button class="s" data-a="netpaste" data-id="nci">📥 Вставить из буфера</button><button data-a="netapply">🔗 Подключиться</button><p id="nst" style="min-height:18px;font-size:12px"></p><button class="s" data-a="netmenu">← Назад</button>`);
  $('nco').value=code;
 }catch(e){scr(`<h1>Ошибка</h1><p>Не удалось создать код: ${esc(e.message||e)}</p><button class="s" data-a="netmenu">← Назад</button>`)}
}
async function netHostApply(){
 try{
  const raw=JSON.parse(await unpack($('nci').value));
  netSt('Подключаюсь…');await netPC.setRemoteDescription(raw);
 }catch(e){netSt('❌ Неверный код ответа')}
}
function netJoinScreen(){
 if(!window.RTCPeerConnection)return toast('Этот браузер не поддерживает WebRTC');
 netQuit(true);netRole='guest';
 scr(`<h1>🔗 Присоединиться</h1><p>Вставь код, который прислал хозяин:</p><textarea id="nci" class="ti" rows="4" placeholder="Код хозяина"></textarea><button class="s" data-a="netpaste" data-id="nci">📥 Вставить из буфера</button><button data-a="netanswer">Продолжить</button><p id="nst" style="min-height:18px;font-size:12px"></p><button class="s" data-a="netmenu">← Назад</button>`);
}
async function netGuestAnswer(){
 let raw;
 try{raw=JSON.parse(await unpack($('nci').value))}catch(e){return netSt('❌ Неверный код')}
 netSt('Готовлю ответ…');
 try{
  const pc=netMk();pc.ondatachannel=e=>netBind(e.channel);
  await pc.setRemoteDescription(raw);await pc.setLocalDescription(await pc.createAnswer());await netGather(pc);
  const code=await pack(JSON.stringify(pc.localDescription));
  if(pc!==netPC)return;
  scr(`<h1>🔗 Присоединиться</h1><p>Отправь этот код ответа хозяину — после этого соединение установится само.</p>${netCodeBlock('nco')}<p id="nst" style="min-height:18px;font-size:12px">Жду подключения…</p><button class="s" data-a="netmenu">← Назад</button>`);
  $('nco').value=code;
 }catch(e){netSt('❌ Ошибка: '+(e.message||e))}
}
